#!/usr/bin/env node
/** Helpers for v3 Production digest pinning. No product logic. */

export const SHA_RE = /^[0-9a-f]{40}$/;
export const DIGEST_RE = /^sha256:[0-9a-f]{64}$/;
export const IMAGE_REPO = "ghcr.io/fyun48/5151";

export function isFullSha(value) {
  return SHA_RE.test(String(value || ""));
}

export function isImageDigest(value) {
  return DIGEST_RE.test(String(value || ""));
}

export function candidateTag(deploySha, repo = IMAGE_REPO) {
  if (!isFullSha(deploySha)) throw new Error("deploy sha must be a full 40-character lowercase hex SHA");
  return `${String(repo).toLowerCase()}:${deploySha}`;
}

export function digestReference(digest, repo = IMAGE_REPO) {
  if (!isImageDigest(digest)) throw new Error("image digest must be sha256: plus 64 lowercase hex chars");
  return `${String(repo).toLowerCase()}@${digest}`;
}

export function composeOverrideYaml(digest, repo = IMAGE_REPO) {
  const image = digestReference(digest, repo);
  return [
    "# Generated by deploy-v3.yml. Pins ONLY 591-tracker-v3.",
    "# v1/v2 keep the image defined in docker-compose.yml.",
    "services:",
    "  591-tracker-v3:",
    `    image: ${image}`,
    "",
  ].join("\n");
}

export function sourceLabelAllowed(label, repository = "Fyun48/5151") {
  const got = String(label || "").trim().toLowerCase();
  const repo = String(repository).trim().toLowerCase();
  return got === `https://github.com/${repo}`;
}

export function assertRevisionMatches(label, deploySha) {
  if (!isFullSha(deploySha)) throw new Error("invalid deploy sha");
  if (String(label || "") !== deploySha) {
    throw new Error(`OCI revision '${label}' != DEPLOY_SHA ${deploySha}`);
  }
}

const self = process.argv[1] ? String(process.argv[1]) : "";
if (self.endsWith("deploy-v3-digest.mjs") && process.argv[2] === "override") {
  process.stdout.write(composeOverrideYaml(process.argv[3]));
}
